<?php if(!defined('SW_APP')||!SW_PUBLIC){http_response_code(404);exit;} $rows=all('SELECT r.title,p.number,p.payment,p.created_at FROM participants p JOIN raffles r ON r.id=p.raffle_id WHERE p.user_id=? ORDER BY p.created_at DESC',[$u['id']]); ?>
<p class="user-sub">Consulta los boletos vinculados a tu cuenta.</p><?php if(!$rows):?><div class="user-empty">Aún no tienes boletos vinculados.</div><?php else:?><div class="user-table"><table><thead><tr><th>Sorteo</th><th>Número</th><th>Pago</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=h($r['number'])?></td><td><?=h(state_name($r['payment']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
